export const getRootAndChildNodes = (nodes) => {
    const rootNodes = [];
    const childNodes = [];
    const nodesAreChildren = {};
    nodes.forEach(node => {
        (node.children || []).forEach(child => {
            nodesAreChildren[child] = true;
        });
        if (!nodesAreChildren[node.id]) {
            nodesAreChildren[node.id] = false;
        }
    });
    nodes.forEach(node => {
        if (nodesAreChildren[node.id]) {
            childNodes.push(node);
        }
        else {
            rootNodes.push(node);
        }
    });
    return { rootNodes, childNodes };
};
