import { useQuery, } from '@tanstack/react-query';
import { useDataProvider } from 'ra-core';
/**
 * Call the dataProvider.getLocks() method and return the resolved locks array,
 * as well as the loading state.
 *
 * @param {string} resource
 * @param {GetLocksParams} params The getLocks parameters { meta }
 * @param {Object} options React Query Options object
 *
 * @returns The locks array for the given resource. Destructure as { data, error, isPending, isFetching }.
 *
 * @example Simple Usage
 *
 * ```tsx
 * const { data } = useGetLocks('posts');
 * ```
 *
 * @example Getting resource from context
 *
 * ```tsx
 * const resource = useResourceContext();
 * const { data: locks } = useGetLocks(resource);
 * ```
 */
export function useGetLocks(resource, params = {}, options = {}) {
    const dataProvider = useDataProvider();
    return useQuery({
        queryKey: [resource, 'getLocks', params],
        queryFn: () => dataProvider.getLocks(resource, params).then(({ data }) => data),
        ...options,
    });
}
