import { useCallback } from 'react';
import { useMutation, useQueryClient, } from '@tanstack/react-query';
import { useDataProvider } from 'ra-core';
import omit from 'lodash/omit';
/**
 * Returns a function allowing to call the dataProvider.lock() method, as well as
 * the react-query mutation handle.
 *
 * @param {string} resource
 * @param {LockParams} params The lock function parameters { id, identity, meta }
 * @param {Object} options React Query Mutation Options object
 *
 * @returns The `lock()` callback as well as the react-query mutation object.
 *
 * @example Simple Usage
 *
 * ```tsx
 * const [lock, _mutation] = useLock('posts', { id: 123, identity: 'mario' });
 * React.useEffect(() => {
 *     lock();
 * }, []);
 * ```
 *
 * @example Call lock with parameters
 *
 * ```tsx
 * const [lock, _mutation] = useLock();
 * React.useEffect(() => {
 *     lock('posts', { id: 123, identity: 'mario' });
 * }, []);
 * ```
 *
 */
export function useLock(resource, params, options = {}) {
    const dataProvider = useDataProvider();
    const queryClient = useQueryClient();
    const updateCache = ({ resource, params, data, }) => {
        const updateColl = (old) => {
            if (!old)
                return;
            const { id: recordId } = params;
            if (!recordId)
                return old;
            const index = old.findIndex(lock => lock.recordId === recordId);
            if (index === -1) {
                return [...old, data];
            }
            return [
                ...old.slice(0, index),
                { ...old[index], ...data },
                ...old.slice(index + 1),
            ];
        };
        queryClient.setQueryData([resource, 'getLock', omit(params, ['identity'])], data);
        queryClient.setQueriesData({
            queryKey: [
                resource,
                'getLocks',
                omit(params, ['identity', 'id']),
            ],
        }, (res) => updateColl(res));
    };
    const mutation = useMutation({
        mutationFn: ({ resource: callTimeResource = resource, params: callTimeParams = params, } = {}) => {
            return dataProvider
                .lock(callTimeResource, callTimeParams)
                .then(({ data }) => {
                return data;
            });
        },
        ...options,
        onSuccess: (data, variables, context) => {
            updateCache({
                resource: variables?.resource || resource,
                params: variables?.params || params,
                data,
            });
            if (options.onSuccess) {
                options.onSuccess(data, variables, context);
            }
        },
    });
    const lock = useCallback((callTimeResource = resource, callTimeParams = params, mutateOptions = options) => {
        return mutation.mutate({ resource: callTimeResource, params: callTimeParams }, mutateOptions);
    }, 
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [mutation.mutate, JSON.stringify({ resource, params, options })]);
    return [lock, mutation];
}
