import { createContext, useContext } from 'react';
import defaults from 'lodash/defaults';
export const ContainerLayoutContext = createContext({});
export const useContainerLayout = (props) => {
    const context = useContext(ContainerLayoutContext);
    return defaults({}, props != null ? extractContainerLayoutProps(props) : {}, context);
};
const extractContainerLayoutProps = ({ hasDashboard, menu, title, toolbar, userMenu, }) => ({
    hasDashboard,
    menu,
    title,
    toolbar,
    userMenu,
});
