import { useCallback, useMemo, useState } from 'react';
import { useSearch } from './dataProvider';
import debounce from 'lodash/debounce';
export const useSearchController = (props) => {
    const { queryOptions, options, wait = 500, disableHighlight = false, } = props;
    const [query, setQuery] = useState('');
    const [search, searchData] = useSearch({
        options,
        queryOptions,
        disableHighlight,
    });
    const debouncedSearch = useMemo(() => debounce(search, wait), [search, wait]);
    const doSearch = useCallback((query) => {
        setQuery(query);
        debouncedSearch(query);
    }, [setQuery, debouncedSearch]);
    return {
        searchData,
        query,
        doSearch,
        disableHighlight,
    };
};
