import { useDataProvider, useEvent } from 'react-admin';
import { useQuery, useQueryClient, } from '@tanstack/react-query';
import { getRootAndChildNodes } from '../util';
import { useEffect } from 'react';
/**
 * Call the dataProvider.getTree() method and return the resolved value
 * as well as the loading state.
 *
 * The return value updates according to the request state:
 *
 * - start: { isLoading: true, refetch }
 * - success: { data: [data from store], total: [total from response], isLoading: false, refetch }
 * - error: { error: [error from response], isLoading: false, refetch }
 *
 * This hook will return the cached result when called a second time
 * with the same parameters, until the response arrives.
 *
 * @param {string} resource The resource name, e.g. 'posts'
 * @param {Params} params The getTree parameters { meta }
 * @param {Object} options Options object to pass to the queryClient.
 * May include side effects to be executed upon success or failure, e.g. { onSuccess: () => { refresh(); } }
 *
 * @typedef Params
 * @prop params.meta Optional meta parameters
 *
 * @returns The current request state. Destructure as { data, error, isLoading, isFetching }.
 *
 * The data structure is a flat array of TreeRecords (i.e. Records with a children field containing an array of Identifiers).
 *
 * @example // sample { data }
 * [
 *   { id: 1, title: 'foo1', children: [3, 4] },
 *   { id: 2, title: 'foo2', children: [] },
 *   { id: 3, title: 'foo3', children: [5] },
 *   { id: 4, title: 'foo4', children: [] },
 *   { id: 5, title: 'foo5', children: [] },
 * ]
 *
 * @example // usage in a React component
 *
 * import { useGetTree } from '@react-admin/ra-tree';
 *
 * const Categories = () => {
 *     const { data: tree, isLoading, error } = useGetTree('categories');
 *     if (isLoading) { return <Loading />; }
 *     if (error) { return <p>ERROR</p>; }
 *     return <Tree tree={data} />;
 * };
 */
export const useGetTree = (resource, params = {}, options) => {
    const dataProvider = useDataProvider();
    const queryClient = useQueryClient();
    const { onSuccess, onError, onSettled, ...restOptions } = options ?? {};
    const result = useQuery({
        queryKey: [resource, 'getTree', params],
        queryFn: () => dataProvider
            .getTree(resource, params)
            .then(({ data }) => data),
        ...restOptions,
    });
    const onSuccessEvent = useEvent(onSuccess ?? (() => undefined));
    const onErrorEvent = useEvent(onError ?? (() => undefined));
    const onSettledEvent = useEvent(onSettled ?? (() => undefined));
    useEffect(() => {
        if (result.data === undefined ||
            result.error != null ||
            result.isFetching)
            return;
        onSuccessEvent(result.data);
    }, [onSuccessEvent, result.data, result.error, result.isFetching]);
    useEffect(() => {
        if (result.error == null || result.isFetching)
            return;
        onErrorEvent(result.error);
    }, [onErrorEvent, result.error, result.isFetching]);
    useEffect(() => {
        if (result.status === 'pending' || result.isFetching)
            return;
        onSettledEvent(result.data, result.error);
    }, [
        onSettledEvent,
        result.data,
        result.error,
        result.isFetching,
        result.status,
    ]);
    useEffect(() => {
        if (!result.data)
            return;
        updateQueryCacheFromGetTree(queryClient, resource, result.data, params);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [JSON.stringify(params), queryClient, resource, result.data]);
    return result;
};
export const updateQueryCacheFromGetTree = (queryClient, resource, data, params) => {
    if (!data) {
        return { rootNodes: [], childNodes: [] };
    }
    const { rootNodes, childNodes } = getRootAndChildNodes(data);
    // optimistically populate the getRootNodes cache
    queryClient.setQueryData([resource, 'getRootNodes', params], oldRecords => oldRecords ?? rootNodes);
    // optimistically populate the getParentNode cache
    childNodes.forEach(record => {
        queryClient.setQueryData([resource, 'getParentNode', { childId: record.id }], oldRecord => oldRecord ??
            data.find(parent => parent.children && parent.children.includes(record.id)));
    });
    // optimistically populate the getChildNodes cache
    data.forEach(record => {
        if (record.children) {
            queryClient.setQueryData([resource, 'getChildNodes', { parentId: record.id }], oldRecords => oldRecords ??
                data.filter(child => record.children?.includes(child.id)));
        }
    });
};
