const sortByDate = (a, b) => new Date(b.date).valueOf() - new Date(a.date).valueOf();
const getDayForAuditLog = (record) => {
    const date = new Date(record.date);
    date.setMilliseconds(0);
    date.setSeconds(0);
    date.setMinutes(0);
    date.setHours(0);
    return date.toISOString();
};
const getDayString = (date, locale) => new Date(date).toLocaleDateString(locale, {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
});
export const groupByDay = (records, locale) => {
    const initialMap = {};
    const map = records.reduce((acc, record) => {
        const label = getDayString(getDayForAuditLog(record), locale);
        acc[label] = acc[label] || [];
        acc[label] = acc[label].concat(record);
        return acc;
    }, initialMap);
    return Object.keys(map).reduce((acc, label) => {
        acc.push({ label, records: map[label].sort(sortByDate) });
        return acc;
    }, []);
};
