import { useCallback } from 'react';
import { useMutationMiddlewares, useNotify, useRecordContext, useResourceContext, useUpdate, } from 'react-admin';
import { useRowContext } from './useRowContext';
/**
 * `useEditableDatagridEditController` is a custom hook for managing the state and logic of an editable data grid.
 *
 * This hook returns an object containing various properties and methods for managing the editable data grid.
 *
 * @param {Object} params The parameters passed to the hook. Expected properties are:
 * - `resource`: The name of the resource being edited.
 * - `record`: The record being edited.
 * - `save`: A callback function that will be called when the record is saved.
 * - `cancel`: A callback function that will be called when the editing is cancelled.
 *
 * @returns {Object} Returns an object with the following properties:
 * - `isEditing`: A boolean indicating whether the data grid is in editing mode.
 * - `setEditing`: A function to set the editing mode.
 * - `editRow`: A function to edit a specific row.
 * - `cancelEdit`: A function to cancel editing.
 * - `saveEdit`: A function to save the edited record.
 */
export const useEditableDatagridEditController = (props = {}) => {
    const { mutationMode, mutationOptions = {}, transform } = props;
    const { close } = useRowContext();
    const resource = useResourceContext(props);
    if (!resource) {
        throw new Error('The DeleteWithConfirmIconButton component must be used inside a ResourceContext or must be passed a record prop.');
    }
    const record = useRecordContext(props);
    if (!record) {
        throw new Error('The DeleteWithConfirmIconButton component must be used inside a RecordContext or must be passed a record prop.');
    }
    const notify = useNotify();
    const { onSuccess, onError, meta: mutationMeta, ...otherMutationOptions } = mutationOptions;
    const { registerMutationMiddleware, getMutateWithMiddlewares, unregisterMutationMiddleware, } = useMutationMiddlewares();
    const updateParams = { id: record.id, previousData: record };
    const [update, { isPending: saving }] = useUpdate(resource, updateParams, {
        onSuccess: async (data, variables, context) => {
            if (onSuccess) {
                return onSuccess(data, variables, context);
            }
            notify('ra.notification.updated', {
                type: 'info',
                messageArgs: {
                    smart_count: 1,
                },
                undoable: mutationMode === 'undoable',
            });
            close();
        },
        onError: (error, variables, context) => {
            if (onError) {
                return onError(error, variables, context);
            }
            const validationErrors = error?.body?.errors;
            const hasValidationErrors = !!validationErrors &&
                Object.keys(validationErrors).length > 0;
            if (!hasValidationErrors || mutationMode !== 'pessimistic') {
                notify(typeof error === 'string'
                    ? error
                    : error.message ||
                        'ra.notification.http_error', {
                    type: 'error',
                    messageArgs: {
                        _: typeof error === 'string'
                            ? error
                            : error instanceof Error ||
                                (typeof error === 'object' &&
                                    error !== null &&
                                    error.hasOwnProperty('message'))
                                ? // @ts-ignore
                                    error.message
                                : undefined,
                    },
                });
            }
        },
        ...otherMutationOptions,
        mutationMode,
        returnPromise: mutationMode === 'pessimistic',
        getMutateWithMiddlewares,
    });
    const save = useCallback(async (data, { onSuccess: onSuccessFromSave, onError: onErrorFromSave, transform: transformFromSave, meta: metaFromSave, } = {}) => Promise.resolve(transformFromSave
        ? transformFromSave(data, {
            previousData: updateParams.previousData,
        })
        : transform
            ? transform(data, {
                previousData: updateParams.previousData,
            })
            : data).then(async (data) => {
        try {
            await update(resource, {
                id: record.id,
                data,
                meta: metaFromSave ?? mutationMeta,
                previousData: updateParams.previousData,
            }, {
                onSuccess: onSuccessFromSave,
                onError: onErrorFromSave,
            });
        }
        catch (error) {
            if (error.body?.errors != null) {
                return error.body.errors;
            }
        }
    }), [
        updateParams.previousData,
        transform,
        update,
        resource,
        record.id,
        mutationMeta,
    ]);
    return {
        save,
        saving,
        registerMutationMiddleware,
        unregisterMutationMiddleware,
    };
};
