const motion = {
    motionName: 'node-motion',
    motionAppear: false,
    onAppearStart: () => ({ height: 0 }),
    onAppearActive: (node) => ({
        height: node.scrollHeight,
    }),
    onLeaveStart: (node) => ({
        height: node.offsetHeight,
    }),
    onLeaveActive: () => ({ height: 0 }),
};
export default motion;
