import { createContext, useContext } from 'react';
export const MultiLevelMenuContext = createContext(null);
export const useMultiLevelMenu = () => {
    const context = useContext(MultiLevelMenuContext);
    if (context == null) {
        throw new Error('useMultiLevelMenu must be used within a MultiLevelMenuContext.Provider');
    }
    return context;
};
