import { useCallback, useEffect, useMemo } from 'react';
import { useDataProvider, useEvent, useSafeSetState } from 'react-admin';
import { useQuery, keepPreviousData, } from '@tanstack/react-query';
/**
 * Get a callback to fetch global search results from the data provider using its `search` method.
 *
 * The request starts when the callback is called.
 *
 * useSearch() parameters can be passed:
 *
 * - at definition time
 *
 *       const [search] = useSearch({ options: { targets: ['artists', 'albums'] } });
 *       search(query);
 *
 * - at call time
 *
 *       const [search] = useSearch();
 *       search(query, { targets: ['artists', 'albums'] });
 *
 * - both, in which case the definition and call time parameters are merged
 *
 *       const [search] = useSearch({ options: { targets: ['artists', 'albums'] } });
 *       search(query, { targets: ['concerts'] });
 *
 * @param {UseSearchOptions} props
 * - {Object} options: Optional. The options used to call the data provider's `search` method.
 * - {Object} queryOptions: Optional. The options used to call the `useQuery` hook.
 *
 * @returns A tuple with the search callback and the request state. Destructure as [search, { query, data, total, error, isPending, isFetched }].
 *
 * The return value updates according to the request state:
 *
 * - mount:         [search, { isPending: true, isFetched: false }]
 * - search called: [search, { isPending: true, isFetched: false }]
 * - success:       [search, { query: [string], data: [data from response], total: [total from response], isPending: false, isFetched: true }]
 * - error:         [search, { query: [string], error: [error from response], isPending: false, isFetched: true }]
 *
 * The search function accepts the following arguments:
 * - {String} query: The terms to search for
 * - {Object} options
 *   - {String[]} targets: Optional. The indices for which the search should be performed.
 */
export const useSearch = (props = {}) => {
    const { options: defaultOptions, queryOptions = {}, disableHighlight = false, } = props;
    const [runQuery, setRunQuery] = useSafeSetState(false);
    const [searchParams, setSearchParams] = useSafeSetState({
        query: '',
        options: {},
    });
    const dataProvider = useDataProvider();
    const { query = '', options = {} } = searchParams ?? {};
    const { onSuccess, onError, onSettled, meta } = queryOptions;
    const searchOptions = {
        ...defaultOptions,
        ...options,
        meta,
    };
    const onSuccessEvent = useEvent(onSuccess ?? (() => undefined));
    const onErrorEvent = useEvent(onError ?? (() => undefined));
    const onSettledEvent = useEvent(onSettled ?? (() => undefined));
    const queryResult = useQuery({
        queryKey: ['search', query, searchOptions],
        queryFn: () => dataProvider.search(query, searchOptions),
        enabled: runQuery,
        placeholderData: keepPreviousData,
        ...(queryOptions || {}),
    });
    useEffect(() => {
        if (queryResult.data === undefined ||
            queryResult.error != null ||
            queryResult.isFetching)
            return;
        onSuccessEvent(queryResult.data);
    }, [
        onSuccessEvent,
        queryResult.data,
        queryResult.error,
        queryResult.isFetching,
    ]);
    useEffect(() => {
        if (queryResult.error == null || queryResult.isFetching)
            return;
        onErrorEvent(queryResult.error);
    }, [onErrorEvent, queryResult.error, queryResult.isFetching]);
    useEffect(() => {
        if (queryResult.status === 'pending' || queryResult.isFetching)
            return;
        setRunQuery(false);
        onSettledEvent(queryResult.data, queryResult.error);
    }, [
        onSettledEvent,
        queryResult.data,
        queryResult.error,
        queryResult.isFetching,
        queryResult.status,
        setRunQuery,
    ]);
    const search = useCallback((query, options = {}) => {
        setSearchParams(() => ({
            query,
            options,
        }));
        setRunQuery(query.length > 0);
    }, [setSearchParams, setRunQuery]);
    const state = useMemo(() => ({
        query,
        ...queryResult,
        data: queryResult.data?.data,
        total: queryResult.data?.total,
        disableHighlight,
    }), [query, queryResult, disableHighlight]);
    return [search, state];
};
