import { useDataProvider, useEvent } from 'ra-core';
import { useMutation, useQueryClient, } from '@tanstack/react-query';
export const useAddRevision = (resource, params, options = {}) => {
    const dataProvider = useDataProvider();
    const queryClient = useQueryClient();
    const mutation = useMutation({
        mutationFn: (args) => {
            const { resource: callTimeRessource = resource, recordId = params?.recordId, data = params?.data, date = params?.date, authorId = params?.authorId, message = params?.message, description = params?.description, } = args;
            return dataProvider.addRevision(callTimeRessource, {
                recordId,
                data,
                date,
                authorId,
                message,
                description,
            });
        },
        onSuccess: (_, callTimeParams) => {
            queryClient.invalidateQueries({
                queryKey: [
                    'getRevisions',
                    callTimeParams?.resource ?? resource,
                    { recordId: callTimeParams?.recordId ?? params?.recordId },
                ],
            });
        },
        ...options,
    });
    const addRevision = async (resource, params, calltimeOptions = {}) => {
        const { returnPromise = options.returnPromise, ...otherOptions } = calltimeOptions;
        return returnPromise
            ? mutation.mutateAsync({ resource, ...params }, otherOptions)
            : mutation.mutate({ resource, ...params }, otherOptions);
    };
    return [useEvent(addRevision), mutation];
};
