import { useEffect, useState, useMemo, useRef } from 'react';
/**
 * Hook to run an async effect on mount and another on unmount.
 *
 * This is necessary because of intricacies of useEffect and StrictMode
 * @see https://beta.reactjs.org/learn/synchronizing-with-effects#fetching-data
 */
export const useAsyncEffect = (mountCallback, unmountCallback, deps = []) => {
    const isMounted = useRef(false);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState(undefined);
    const [result, setResult] = useState();
    useEffect(() => {
        isMounted.current = true;
        return () => {
            isMounted.current = false;
        };
    }, []);
    useEffect(() => {
        let ignore = false;
        let mountSucceeded = false;
        (async () => {
            await Promise.resolve(); // wait for the initial unmount in Strict mode - avoids double mutation
            if (!isMounted.current || ignore) {
                return;
            }
            setIsLoading(true);
            try {
                const result = await mountCallback();
                mountSucceeded = true;
                if (isMounted.current && !ignore) {
                    setError(undefined);
                    setResult(result);
                    setIsLoading(false);
                }
                else {
                    // Component was unmounted before the mount callback returned, cancel it
                    unmountCallback();
                }
            }
            catch (error) {
                if (!isMounted.current)
                    return;
                setError(error);
                setIsLoading(false);
            }
        })();
        return () => {
            ignore = true;
            if (mountSucceeded) {
                unmountCallback()
                    .then(() => {
                    if (!isMounted.current)
                        return;
                    setResult(undefined);
                })
                    .catch((error) => {
                    if (!isMounted.current)
                        return;
                    setError(error);
                });
            }
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, deps);
    return useMemo(() => ({ result, error, isLoading }), [result, error, isLoading]);
};
