/**
 * Turn a flat array of TreeRecords into a tree structure,
 * where each tree has an array of TreeRecords as children.
 *
 * @example
 *
 * getRecordTree([
 *   { id: 1, title: 'foo1', children: [3, 4] },
 *   { id: 2, title: 'foo2', children: [] },
 *   { id: 3, title: 'foo3', children: [5] },
 *   { id: 4, title: 'foo4', children: [] },
 *   { id: 5, title: 'foo5', children: [] },
 * ]);
 * => [
 *   { id: 1, title: 'foo1', children: [
 *     { id: 3, title: 'foo3', children: [
 *       { id: 5, title: 'foo5', children: [] },
 *     ] },
 *     { id: 4, title: 'foo4', children: [] },
 *   ] },
 *   { id: 2, title: 'foo2', children: [] },
 * ]
 */
const getRecordTree = (nodes) => {
    const nodesById = nodes.reduce((acc, curr) => {
        acc[curr.record.id] = curr;
        return acc;
    }, {});
    const childRecordIds = Array.from(new Set(nodes.flatMap(node => node.record.children)));
    const rootNodes = nodes.filter(({ record }) => !childRecordIds.includes(record.id));
    const addChildren = (node, recordId) => ({
        // Those two lines ensure we have the minimum props needed for rc-tree
        // even though we may not have loaded the records yet (lazy mode)
        ...node,
        id: recordId,
        key: recordId.toString(),
        children: (node?.record.children || []).map(id => addChildren(nodesById[id], id)),
        isLeaf: !!(node?.record.children && node.record.children.length === 0),
    });
    return rootNodes.map(node => addChildren(node, node.record.id));
};
export default getRecordTree;
