import { createContext, useContext } from 'react';
export const SolarMenuContext = createContext(null);
export const useSolarMenuContext = () => {
    const context = useContext(SolarMenuContext);
    if (context === null) {
        throw new Error('useSolarMenuContext must be used inside a SolarMenuContextProvider');
    }
    return context;
};
export const SolarMenuContextProvider = SolarMenuContext.Provider;
